// Generates supabase/seed/config.sql from content/. Idempotent SQL: safe to apply on every deploy.
import { writeFileSync } from 'node:fs'
import { config } from '../content/config.ts'

export function buildSeedSql(): string {
  const rows = Object.entries(config)
    .map(([key, value]) => `  ('${key.replace(/'/g, "''")}', '${JSON.stringify(value).replace(/'/g, "''")}'::jsonb)`)
    .join(',\n')
  return [
    '-- GENERATED by scripts/gen-seed.ts from content/. Do not edit by hand.',
    'insert into game.config (key, value) values',
    rows,
    'on conflict (key) do update set value = excluded.value;',
    '',
  ].join('\n')
}

if (process.argv[1]?.endsWith('gen-seed.ts')) {
  writeFileSync(new URL('../supabase/seed/config.sql', import.meta.url), buildSeedSql())
  console.log('wrote supabase/seed/config.sql')
}
